"use client";
import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/pixel3d";
import { Button, type ButtonProps } from "@/components/ui/button";
import { nameTagClasses } from "@/components/ui/input";

/**
 * InputGroup — a name-tag field whose writing panel holds addons next to the text:
 * a prefix like `https://`, a pixel icon, a Kbd hint or a small Copy button.
 *
 *   <InputGroup label="Demo link">
 *     <InputGroupAddon><InputGroupText>https://</InputGroupText></InputGroupAddon>
 *     <InputGroupInput placeholder="null-pointers.dev" />
 *     <InputGroupAddon align="inline-end"><InputGroupButton aria-label="Copy"><Copy /></InputGroupButton></InputGroupAddon>
 *   </InputGroup>
 */
const InputGroupContext = React.createContext<{ id?: string; invalid: boolean; disabled?: boolean }>({
  invalid: false,
});

export interface InputGroupProps extends React.ComponentPropsWithoutRef<"div"> {
  label?: React.ReactNode;
  /** Replaces the label in the band while invalid. Name the problem + the fix. */
  error?: React.ReactNode;
  disabled?: boolean;
  /** id for the control inside (InputGroupInput / InputGroupTextarea pick it up). */
  controlId?: string;
  /** Classes for the white writing panel. */
  panelClassName?: string;
}

export const InputGroup = React.forwardRef<HTMLDivElement, InputGroupProps>(
  ({ className, panelClassName, label, error, disabled, controlId, children, ...props }, ref) => {
    const autoId = React.useId();
    const id = controlId ?? autoId;
    const invalid = Boolean(error) || props["aria-invalid"] === true || props["aria-invalid"] === "true";
    const hasBand = Boolean(label || error);
    const ctx = React.useMemo(() => ({ id, invalid, disabled }), [id, invalid, disabled]);
    return (
      <InputGroupContext.Provider value={ctx}>
        <div
          ref={ref}
          role="group"
          data-slot="input-group"
          data-invalid={invalid || undefined}
          data-disabled={disabled || undefined}
          className={cn(nameTagClasses({ hasBand, invalid, disabled }), className)}
          {...props}
        >
          {hasBand && (
            <label htmlFor={id} className="px-3 pt-1 pb-2 text-base font-bold leading-tight">
              {invalid && error ? error : label}
            </label>
          )}
          <div
            data-slot="input-group-panel"
            className={cn("flex min-h-12 flex-wrap items-center gap-x-2 bg-paper px-3 text-ink", panelClassName)}
          >
            {children}
          </div>
        </div>
      </InputGroupContext.Provider>
    );
  }
);
InputGroup.displayName = "InputGroup";

export const inputGroupAddonVariants = cva(
  "flex shrink-0 cursor-text select-none items-center gap-2 text-lg font-medium text-ink-soft [&_svg]:pixel-icon [&_svg]:size-6",
  {
    variants: {
      align: {
        "inline-start": "order-first",
        "inline-end": "order-last",
        "block-start": "order-first basis-full pt-3",
        "block-end": "order-last basis-full justify-between pb-3",
      },
    },
    defaultVariants: { align: "inline-start" },
  }
);

export const InputGroupAddon = React.forwardRef<
  HTMLDivElement,
  React.ComponentPropsWithoutRef<"div"> & VariantProps<typeof inputGroupAddonVariants>
>(({ className, align = "inline-start", onClick, ...props }, ref) => (
  <div
    ref={ref}
    role="group"
    data-slot="input-group-addon"
    data-align={align}
    className={cn(inputGroupAddonVariants({ align }), className)}
    onClick={(e) => {
      onClick?.(e);
      // clicking a text/icon addon writes into the field, like a real label
      if ((e.target as HTMLElement).closest("button")) return;
      e.currentTarget.parentElement?.querySelector<HTMLElement>("input, textarea")?.focus();
    }}
    {...props}
  />
));
InputGroupAddon.displayName = "InputGroupAddon";

export const InputGroupText = React.forwardRef<HTMLSpanElement, React.ComponentPropsWithoutRef<"span">>(
  ({ className, ...props }, ref) => (
    <span
      ref={ref}
      data-slot="input-group-text"
      className={cn("flex items-center gap-2 whitespace-nowrap text-lg font-medium text-ink-soft", className)}
      {...props}
    />
  )
);
InputGroupText.displayName = "InputGroupText";

export interface InputGroupButtonProps extends Omit<ButtonProps, "size"> {
  size?: "sm" | "icon-sm";
}

/** A small, straight sticker button that lives inside the writing panel. */
export const InputGroupButton = React.forwardRef<HTMLButtonElement, InputGroupButtonProps>(
  ({ className, size = "sm", variant = "ink", tilt = false, type = "button", ...props }, ref) => (
    <Button
      ref={ref}
      type={type}
      variant={variant}
      tilt={tilt}
      size={size === "icon-sm" ? "icon" : "sm"}
      data-slot="input-group-button"
      className={cn(size === "icon-sm" ? "size-9 [&_svg]:size-5" : "h-9 px-3 text-base [&_svg]:size-5", className)}
      {...props}
    />
  )
);
InputGroupButton.displayName = "InputGroupButton";

export const InputGroupInput = React.forwardRef<HTMLInputElement, React.ComponentPropsWithoutRef<"input">>(
  ({ className, id, disabled, ...props }, ref) => {
    const ctx = React.useContext(InputGroupContext);
    return (
      <input
        ref={ref}
        id={id ?? ctx.id}
        disabled={disabled ?? ctx.disabled}
        aria-invalid={ctx.invalid || undefined}
        data-slot="input-group-control"
        className={cn(
          "h-12 min-w-0 flex-1 bg-transparent text-lg font-medium text-ink outline-none placeholder:text-placeholder disabled:cursor-not-allowed",
          className
        )}
        {...props}
      />
    );
  }
);
InputGroupInput.displayName = "InputGroupInput";

export const InputGroupTextarea = React.forwardRef<HTMLTextAreaElement, React.ComponentPropsWithoutRef<"textarea">>(
  ({ className, id, disabled, ...props }, ref) => {
    const ctx = React.useContext(InputGroupContext);
    return (
      <textarea
        ref={ref}
        id={id ?? ctx.id}
        disabled={disabled ?? ctx.disabled}
        aria-invalid={ctx.invalid || undefined}
        data-slot="input-group-control"
        className={cn(
          "min-h-24 w-full min-w-0 flex-1 resize-none bg-transparent py-3 text-lg font-medium text-ink outline-none placeholder:text-placeholder disabled:cursor-not-allowed",
          className
        )}
        {...props}
      />
    );
  }
);
InputGroupTextarea.displayName = "InputGroupTextarea";

"use client";
import * as React from "react";
import { cn } from "@/lib/pixel3d";

/**
 * Input — a name-tag sticker. The label lives in the coloured band ("HELLO my name is");
 * you write on the white panel below. The band carries state:
 * rest = ink, focus = sky, invalid = tomato (band shows the error), disabled = blank.
 * Fields never tilt (The Crooked Rule).
 *
 *   <Input label="Team name" placeholder="Null Pointers" />
 *   <Input aria-label="Search" leading={<Search />} />   // no band: a plain white tag
 */
export interface InputProps extends React.InputHTMLAttributes<HTMLInputElement> {
  label?: React.ReactNode;
  /** Replaces the label in the band while invalid. Name the problem + the fix. */
  error?: React.ReactNode;
  leading?: React.ReactNode;
  trailing?: React.ReactNode;
  wrapperClassName?: string;
}

export function nameTagClasses({ hasBand, invalid, disabled }: { hasBand: boolean; invalid: boolean; disabled?: boolean }) {
  return cn(
    "group/tag sticker sticker-lg focus-within-cut flex w-full flex-col p-2",
    hasBand ? "face-ink focus-within:face-sky focus-within:text-ink" : "face-paper",
    invalid && "face-tomato focus-within:face-tomato text-ink",
    disabled && "[--face:#e4e6ea] text-ink-soft"
  );
}

export const Input = React.forwardRef<HTMLInputElement, InputProps>(
  ({ className, wrapperClassName, label, error, trailing, leading, id, disabled, ...props }, ref) => {
    const autoId = React.useId();
    const inputId = id ?? autoId;
    const invalid = Boolean(error) || props["aria-invalid"] === true || props["aria-invalid"] === "true";
    const hasBand = Boolean(label || error);
    return (
      <div
        data-slot="input"
        data-invalid={invalid || undefined}
        data-disabled={disabled || undefined}
        className={cn(nameTagClasses({ hasBand, invalid, disabled }), wrapperClassName)}
      >
        {hasBand && (
          <label htmlFor={inputId} className="px-3 pt-1 pb-2 text-base font-bold leading-tight">
            {invalid && error ? error : label}
          </label>
        )}
        <div className="flex h-12 items-center gap-2 bg-paper px-3 text-ink">
          {leading && <span className="flex shrink-0 text-ink-soft [&_svg]:pixel-icon [&_svg]:size-6">{leading}</span>}
          <input
            ref={ref}
            id={inputId}
            disabled={disabled}
            aria-invalid={invalid || undefined}
            className={cn(
              "h-full min-w-0 flex-1 bg-transparent text-lg font-medium text-ink outline-none placeholder:text-placeholder disabled:cursor-not-allowed",
              className
            )}
            {...props}
          />
          {trailing && (
            <span className="flex shrink-0 items-center text-ink-soft [&_svg]:pixel-icon [&_svg]:size-6">{trailing}</span>
          )}
        </div>
      </div>
    );
  }
);
Input.displayName = "Input";

"use client";
import * as React from "react";
import { Slot } from "radix-ui";
import { cva, type VariantProps } from "class-variance-authority";
import { cn, useTilt, type Tilt } from "@/lib/pixel3d";

/**
 * Button — a die-cut sticker that peels on hover and slaps on press.
 * Variants map to inks: primary = pink (act), secondary = paper, success = lime,
 * destructive = tomato, ink = black sticker, ghost = no sticker (text + icon only).
 */
export const buttonVariants = cva(
  "sticker sticker-disabled focus-cut peel inline-flex select-none items-center justify-center gap-2.5 whitespace-nowrap font-p3d font-extrabold tracking-[-0.01em] cursor-pointer [&_svg]:pixel-icon [&_svg]:shrink-0",
  {
    variants: {
      variant: {
        primary: "face-pink",
        secondary: "face-paper",
        success: "face-lime",
        destructive: "face-tomato",
        ink: "face-ink",
        ghost: "[filter:none] before:hidden text-on-lid hover:bg-on-lid/10",
      },
      size: {
        sm: "h-10 px-4 text-base [&_svg]:size-4",
        md: "h-12 px-5 text-lg [&_svg]:size-6",
        lg: "h-14 px-7 text-xl [&_svg]:size-6",
        icon: "size-12 [&_svg]:size-6",
      },
    },
    defaultVariants: { variant: "primary", size: "md" },
  }
);

export interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof buttonVariants> {
  asChild?: boolean;
  /** Resting angle. "auto" (default) picks a stable crooked angle; false = straight. */
  tilt?: Tilt;
  /** Shows a pixel spinner and blocks interaction. */
  loading?: boolean;
}

export const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  (
    { className, variant, size, asChild = false, tilt = "auto", loading = false, style, children, disabled, ...props },
    ref
  ) => {
    const Comp = asChild ? Slot.Root : "button";
    const tiltStyle = useTilt(variant === "ghost" ? false : tilt);
    return (
      <Comp
        ref={ref}
        data-slot="button"
        className={cn(buttonVariants({ variant, size }), className)}
        style={{ ...tiltStyle, ...style }}
        disabled={asChild ? undefined : disabled || loading}
        aria-disabled={asChild && disabled ? true : undefined}
        aria-busy={loading || undefined}
        {...props}
      >
        {loading && !asChild ? (
          <>
            <PixelSpinner />
            {children}
          </>
        ) : (
          children
        )}
      </Comp>
    );
  }
);
Button.displayName = "Button";

/** 8-block pixel spinner; rotates in steps so it reads as pixel art. */
export function PixelSpinner({ className, size = 20, label }: { className?: string; size?: number; label?: string }) {
  return (
    <svg
      viewBox="0 0 10 10"
      width={size}
      height={size}
      role={label ? "status" : undefined}
      aria-label={label}
      aria-hidden={label ? undefined : true}
      className={cn("pixel-icon animate-[p3d-pixel-spin_800ms_steps(8)_infinite]", className)}
      fill="currentColor"
    >
      <rect x="4" y="0" width="2" height="2" />
      <rect x="7" y="1.5" width="2" height="2" opacity=".85" />
      <rect x="8" y="4" width="2" height="2" opacity=".7" />
      <rect x="7" y="6.5" width="2" height="2" opacity=".55" />
      <rect x="4" y="8" width="2" height="2" opacity=".4" />
      <rect x="1" y="6.5" width="2" height="2" opacity=".3" />
      <rect x="0" y="4" width="2" height="2" opacity=".2" />
      <rect x="1" y="1.5" width="2" height="2" opacity=".12" />
    </svg>
  );
}
